"""Markdown + JSON report assembly for a reference video."""

from __future__ import annotations

from .palette import contrast_profile


def build_markdown(analysis: dict) -> str:
    v = analysis.get("video") or {}
    a = analysis.get("audio") or {}
    sc = analysis.get("scenes") or {}
    pal = analysis.get("palette") or {}
    mo = analysis.get("motion") or {}
    act = (analysis.get("audio_analysis") or {}).get("activity") or {}
    stats = sc.get("shot_duration_stats") or {}

    lines = [
        f"# Reference analysis — `{analysis.get('file')}`",
        "",
        "> Generated by `scripts/analyze_reference.py`. Every number below comes from",
        "> FFmpeg/FFprobe measurements on the file, not from assumptions.",
        "",
        "## Container & streams",
        "",
        f"- Duration: **{analysis.get('duration')} s**",
        f"- Container: `{analysis.get('container')}` · {analysis.get('size_bytes', 0) / 1e6:.2f} MB",
        f"- Video: `{v.get('codec')}` {v.get('width')}×{v.get('height')} @ {v.get('fps')} fps "
        f"({v.get('orientation')}, AR {v.get('aspect')})",
        f"- Audio: `{a.get('codec')}` {a.get('channels')} ch @ {a.get('sample_rate')} Hz",
        "",
        "## Editing rhythm",
        "",
        f"- Hard cuts (scene>0.30): **{sc.get('cut_count_hard')}**",
        f"- Soft changes (scene>0.10): **{sc.get('cut_count_soft')}** "
        f"({sc.get('cuts_per_minute_soft')} per minute)",
        f"- Detected shots: **{sc.get('shot_count')}** · mean {stats.get('mean')} s · "
        f"median {stats.get('median')} s · max {stats.get('max')} s",
        "",
        "| # | start | end | duration |",
        "|---|---|---|---|",
    ]
    for shot in (sc.get("shots") or [])[:40]:
        lines.append(
            f"| {shot['index']} | {shot['start']:.2f}s | {shot['end']:.2f}s | {shot['duration']:.2f}s |"
        )

    lines += [
        "",
        "## Palette (k-means, dominant first)",
        "",
        "| swatch | hex | share | hue | lightness |",
        "|---|---|---|---|---|",
    ]
    for entry in (pal.get("palette") or []):
        lines.append(
            f"| ![](https://placehold.co/24x24/{entry['hex'][1:]}/{entry['hex'][1:]}?text=+) "
            f"| `{entry['hex']}` | {entry['share'] * 100:.1f}% | {entry['hue']}° | {entry['lightness']} |"
        )
    cp = contrast_profile(pal.get("palette") or [])
    lines += [
        "",
        f"Mean frame colour: `{pal.get('mean_hex')}` · tonal spread "
        f"shadow {cp['shadow'] * 100:.1f}% / mid {cp['mid'] * 100:.1f}% / highlight {cp['highlight'] * 100:.1f}%",
        "",
        "## Motion",
        "",
        f"- Mean inter-frame energy: {mo.get('mean_motion_energy')} (median {mo.get('median_motion_energy')})",
        f"- Frames with meaningful change: {mo.get('moving_ratio')}",
        f"- Frames with horizontal shift: {mo.get('pan_ratio')} · vertical: {mo.get('tilt_ratio')}",
        f"- Median |pan| {mo.get('median_abs_pan_px')} px, |tilt| {mo.get('median_abs_tilt_px')} px",
        "",
        "## Audio",
        "",
        f"- Mean / peak level: {analysis.get('audio_analysis', {}).get('loudness')}",
        f"- Activity ratio: {act.get('active_ratio')} (gate {act.get('gate_db')} dB)",
        f"- Active segments: {len(act.get('segments') or [])} · gaps: {len(act.get('gaps') or [])}",
        "",
        "> Note: the activity detector is level-based. It cannot identify speakers,",
        "> language or music vs. speech without a transcription model.",
        "",
        "## Extracted review frames",
        "",
        f"- {len(analysis.get('frames') or [])} frames in `frames/`",
        f"- Contact sheet: `{analysis.get('contact_sheet')}`" if analysis.get("contact_sheet") else "",
        "",
    ]
    return "\n".join(lines)
